using System.ComponentModel;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Configuration – set via environment variables
// ---------------------------------------------------------------------------
var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "";
var baseUrl = Environment.GetEnvironmentVariable("OPENAI_BASE_URL");

if (string.IsNullOrWhiteSpace(apiKey))
{
    Console.Error.WriteLine("Set OPENAI_API_KEY (and optionally OPENAI_BASE_URL / OPENAI_MODEL).");
    return 1;
}

// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------
var notebook = new Notebook();

IChatClient innerClient = string.IsNullOrEmpty(baseUrl)
    ? new OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient()
    : new OpenAIClient(new System.ClientModel.ApiKeyCredential(apiKey),
          new OpenAIClientOptions { Endpoint = new Uri(baseUrl) })
        .GetChatClient(modelId).AsIChatClient();

IChatClient agent = innerClient
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(
        ([Description("The search query")] string query) =>
        {
            Console.WriteLine($"  🔍  Searching: {query}");
            return WebSearch.SearchAsync(query);
        },
        "web_search",
        "Search the web for information on a topic. Returns a list of result snippets."),
    AIFunctionFactory.Create(
        ([Description("A concise title for the note")] string title,
         [Description("The content of the note")] string content) =>
        {
            notebook.Add(title, content);
            Console.WriteLine($"  📝  Note saved: {title}");
            return $"Note \"{title}\" saved.";
        },
        "save_note",
        "Save a research note for later summarisation."),
    AIFunctionFactory.Create(
        () =>
        {
            var notes = notebook.GetAll();
            Console.WriteLine($"  📖  Reading {notes.Count} note(s)");
            return notes;
        },
        "read_notes",
        "Read all previously saved research notes.")
};

// ---------------------------------------------------------------------------
// Prompt & agent loop
// ---------------------------------------------------------------------------
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.Error.WriteLine("No topic provided.");
    return 1;
}

Console.WriteLine($"\n🤖 Researching: {topic}\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your goal is to thoroughly research a topic
        provided by the user.

        Workflow:
        1. Break the topic into 2-3 sub-questions.
        2. For each sub-question, call `web_search` to find relevant information.
        3. After each search, call `save_note` to record key findings.
        4. When you have enough material, call `read_notes` to review everything.
        5. Finally, produce a well-structured summary with sections and citations.

        Be concise but thorough. Cite sources where possible.
        """),
    new(ChatRole.User, $"Research the following topic and provide a summary: {topic}")
};

var options = new ChatOptions { Tools = tools };

var response = await agent.GetResponseAsync(messages, options);

Console.WriteLine("\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
Console.WriteLine("📋  RESEARCH SUMMARY");
Console.WriteLine("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n");
Console.WriteLine(response.Text);
Console.WriteLine();

return 0;

// ═══════════════════════════════════════════════════════════════════════════
// Supporting types
// ═══════════════════════════════════════════════════════════════════════════

/// <summary>Simple in-memory notebook for collecting research notes.</summary>
sealed class Notebook
{
    private readonly List<Note> _notes = [];

    public void Add(string title, string content) =>
        _notes.Add(new Note(title, content, DateTime.UtcNow));

    public IReadOnlyList<Note> GetAll() => _notes.AsReadOnly();

    public record Note(string Title, string Content, DateTime SavedAt);
}

/// <summary>Web search using DuckDuckGo Instant Answer API (no key required).</summary>
static class WebSearch
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders = { { "User-Agent", "ResearchAgent/1.0" } }
    };

    public static async Task<string> SearchAsync(string query)
    {
        try
        {
            // DuckDuckGo Instant Answer API – free, no key needed
            var url = $"https://api.duckduckgo.com/?q={Uri.EscapeDataString(query)}&format=json&no_html=1";
            var json = await Http.GetStringAsync(url);
            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new StringBuilder();

            // Abstract (main answer)
            var abs = root.GetProperty("Abstract").GetString();
            var absSource = root.GetProperty("AbstractSource").GetString();
            var absUrl = root.GetProperty("AbstractURL").GetString();
            if (!string.IsNullOrWhiteSpace(abs))
                results.AppendLine($"**{absSource}**: {abs}\nSource: {absUrl}\n");

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                int count = 0;
                foreach (var t in topics.EnumerateArray())
                {
                    if (count >= 5) break;
                    var text = t.TryGetProperty("Text", out var tv) ? tv.GetString() : null;
                    var link = t.TryGetProperty("FirstURL", out var lu) ? lu.GetString() : null;
                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        results.AppendLine($"- {text}");
                        if (!string.IsNullOrWhiteSpace(link))
                            results.AppendLine($"  Source: {link}");
                        count++;
                    }
                }
            }

            var output = results.ToString().Trim();
            return string.IsNullOrWhiteSpace(output)
                ? $"No detailed results found for \"{query}\". Try rephrasing or breaking into smaller queries."
                : output;
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }
}

